BEGIN;
ALTER TABLE public.hero_items ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE public.post ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS caption_bn text, ADD COLUMN IF NOT EXISTS caption_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text, ADD COLUMN IF NOT EXISTS content_bn text, ADD COLUMN IF NOT EXISTS content_en text;
ALTER TABLE public.pages ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text, ADD COLUMN IF NOT EXISTS content_bn text, ADD COLUMN IF NOT EXISTS content_en text;
ALTER TABLE public.albums ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text, ADD COLUMN IF NOT EXISTS description_bn text, ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE public.widgets ADD COLUMN IF NOT EXISTS title_bn text, ADD COLUMN IF NOT EXISTS title_en text;
UPDATE public.hero_items SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END WHERE title_bn IS NULL OR title_en IS NULL OR description_bn IS NULL OR description_en IS NULL;
UPDATE public.post SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,caption_bn=CASE WHEN COALESCE(caption,'') ~ '[ঀ-৿]' THEN caption ELSE caption_bn END,caption_en=CASE WHEN COALESCE(caption,'')<>'' AND caption !~ '[ঀ-৿]' THEN caption ELSE caption_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END,content_bn=CASE WHEN COALESCE(content,'') ~ '[ঀ-৿]' THEN content ELSE content_bn END,content_en=CASE WHEN COALESCE(content,'')<>'' AND content !~ '[ঀ-৿]' THEN content ELSE content_en END WHERE title_bn IS NULL OR title_en IS NULL OR caption_bn IS NULL OR caption_en IS NULL OR description_bn IS NULL OR description_en IS NULL OR content_bn IS NULL OR content_en IS NULL;
UPDATE public.pages SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END,content_bn=CASE WHEN COALESCE(content,'') ~ '[ঀ-৿]' THEN content ELSE content_bn END,content_en=CASE WHEN COALESCE(content,'')<>'' AND content !~ '[ঀ-৿]' THEN content ELSE content_en END WHERE title_bn IS NULL OR title_en IS NULL OR description_bn IS NULL OR description_en IS NULL OR content_bn IS NULL OR content_en IS NULL;
UPDATE public.albums SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END,description_bn=CASE WHEN COALESCE(description,'') ~ '[ঀ-৿]' THEN description ELSE description_bn END,description_en=CASE WHEN COALESCE(description,'')<>'' AND description !~ '[ঀ-৿]' THEN description ELSE description_en END WHERE title_bn IS NULL OR title_en IS NULL OR description_bn IS NULL OR description_en IS NULL;
UPDATE public.widgets SET title_bn=CASE WHEN title ~ '[ঀ-৿]' THEN title ELSE title_bn END,title_en=CASE WHEN title !~ '[ঀ-৿]' THEN title ELSE title_en END WHERE title_bn IS NULL OR title_en IS NULL;

-- Seed the English counterparts of the existing, locally supplied public pages.
UPDATE public.pages SET title_en=$t$Population & Occupations$t$,description_en=$d$Estimated population of Dalimgari village, age-group figures, and occupational proportions.$d$,content_en=$h$<h2>Population and Households</h2>
<ul><li><strong>Total population:</strong> Approximately 500 people</li><li><strong>Households:</strong> Approximately 100</li></ul>
<h2>Population by Age Group</h2>
<table><thead><tr><th>Group</th><th>Number</th></tr></thead><tbody>
<tr><td>Older adults</td><td>50 people</td></tr><tr><td>Middle-aged adults</td><td>250 people</td></tr><tr><td>Youth</td><td>150 people</td></tr><tr><td>Children</td><td>50 people</td></tr><tr><th>Total</th><th>500 people</th></tr></tbody></table>
<h2>Number of Women and Men</h2><p>The source information contains inconsistencies in the figures for women and men. Separate figures have therefore not been published on this page until they can be verified.</p>
<h2>Occupational Proportions</h2><table><thead><tr><th>Occupation</th><th>Reported Approximate Rate</th></tr></thead><tbody>
<tr><td>Farmers</td><td>50%</td></tr><tr><td>Business owners and traders</td><td>20%</td></tr><tr><td>Salaried employees</td><td>20%</td></tr><tr><td>Other employment</td><td>5%</td></tr><tr><td>Unemployed</td><td>5%</td></tr></tbody></table>
<p><em>These are approximate figures supplied locally. It has not been confirmed whether the occupational percentages refer to the total population or the working-age population. The age-group boundaries have also not been specified.</em></p>$h$ WHERE url='population-occupation';

UPDATE public.pages SET title_en=$t$Education & Religious Institutions$t$,description_en=$d$An overview of schools, mosques, maktabs, and cemeteries in Dalimgari village.$d$,content_en=$h$<h2>Mosques</h2><p>There are two mosques at opposite ends of the village. They are important institutions in the religious life of local residents.</p>
<h2>Maktab</h2><p>It has been reported that an open maktab operates at one of the mosques. Children have the opportunity to learn basic Islamic teachings there free of charge.</p>
<h2>Schools and Education</h2><p>Local accounts indicate that there is a semi-governmental BRAC school in the village where children receive primary education. For secondary and higher-secondary education, residents can travel to nearby Kamdia Bazar.</p>
<h2>Cemeteries</h2><p>There are two cemeteries adjoining the village. Two additional cemeteries are located nearby and are used for burials when needed.</p>
<p><em>The institutions' official names, administrative status, and exact locations have not yet been independently verified.</em></p>$h$ WHERE url='education-religious-institutions';

UPDATE public.pages SET title_en=$t$Notable Places in the Village$t$,description_en=$d$Information about Bat-tola and Magurer Beel, two well-known places in Dalimgari village.$d$,content_en=$h$<h2>Bat-tola</h2><p>Bat-tola is a well-known place located at the very centre of Dalimgari village. Because of its central location, several grocery shops have developed there. The area is familiar and lively because residents pass through, shop for everyday necessities, and gather to talk.</p>
<h2>Magurer Beel</h2><p>Magurer Beel is a pond or waterbody located in the centre of the village. Local accounts say Bat-tola developed on the bank of this waterbody.</p>
<p>According to local tradition, the mosque authorities have been farming magur (walking catfish) in this pond for a long time. The place became known as Magurer Beel because of this fish-farming tradition.</p>
<p><em>The account of the name Magurer Beel and its fish-farming history is based on information passed down locally.</em></p>$h$ WHERE url='local-places';

UPDATE public.pages SET title_en=$t$Village Overview$t$,description_en=$d$A brief introduction to Dalimgari village, including administrative details, area, population, and main livelihoods.$d$,content_en=$h$<p><strong>Dalimgari</strong> is a village in Gobindaganj Upazila, Gaibandha District, in Bangladesh's Rangpur Division. Local traditions, an agriculture-based way of life, and rural social institutions are part of the village's identity.</p>
<h2>Dalimgari at a Glance</h2><ul><li><strong>Mouza:</strong> Chhatiancura</li><li><strong>Post office:</strong> Kamdia</li><li><strong>Upazila and police station:</strong> Gobindaganj</li><li><strong>District:</strong> Gaibandha</li><li><strong>Division:</strong> Rangpur</li><li><strong>Area:</strong> Approximately 1 square kilometre</li><li><strong>Population:</strong> Approximately 500 people</li><li><strong>Households:</strong> Approximately 100</li><li><strong>Main occupation:</strong> Agriculture</li><li><strong>Main crops:</strong> Rice; potatoes are the second major crop</li></ul>
<h2>Village Life</h2><p>Dalimgari is an agriculture-based village. In addition to rice and potatoes, small quantities of various fruits, vegetables, and other crops are produced. Local accounts indicate that the village has two mosques, a maktab, and a BRAC school.</p>
<h2>Learn More</h2><ul><li><a href="?page=history-naming">History &amp; Naming</a></li><li><a href="?page=geography-location">Geography &amp; Location</a></li><li><a href="?page=population-occupation">Population &amp; Occupations</a></li><li><a href="?page=agriculture-economy">Agriculture &amp; Economy</a></li><li><a href="?page=education-religious-institutions">Education &amp; Religious Institutions</a></li><li><a href="?page=local-places">Notable Places in the Village</a></li></ul>
<p><em>The figures shown here are approximate local information and have not been verified as official statistics.</em></p>$h$ WHERE url='village-overview';

UPDATE public.pages SET title_en=$t$History & Naming$t$,description_en=$d$The origins of Dalimgari village, settlement before the Liberation War, local naming traditions, and its connection with Chhatiancura.$d$,content_en=$h$<h2>Origins of the Village</h2><p>The identity of the first person or family to establish Dalimgari, as well as its exact founding date, is not known with certainty. Local tradition holds that people came from neighbouring villages and settled here; over time, the settlement developed into a distinct village.</p>
<h2>Memories of the Liberation War</h2><p>According to older residents, people were living in Dalimgari during Bangladesh's Liberation War. Local accounts say that many villagers participated in the war directly or indirectly. Details about specific individuals or events have not yet been documented here.</p>
<h2>First Naming Tradition: The Pomegranate Fruit</h2><p>One local tradition says that village residents and elders invited the respected Islamic figure Syed Wazed (RA) when they wanted to establish an identity and name for the village. Pomegranates (dalim) were served during the hospitality, and the story holds that he was pleased by the fruit and named the village Dalimgari.</p>
<h2>Second Naming Tradition: A Pomegranate Tree</h2><p>Another story says that Syed Wazed (RA) planted a pomegranate tree beside the pond at the Jame Mosque. According to this account, the village came to be called Dalimgari because of that tree.</p>
<p><strong>Historical note:</strong> Both accounts are local traditions. No evidence has yet been found to establish which, if either, is the actual origin of the village's name.</p>
<h2>Connection with Chhatiancura</h2><p>According to local accounts, many of Dalimgari's early residents had previously lived in Chhatiancura. People from other areas later settled here as well. Dalimgari is now locally known as a distinct village, while its mouza designation is Chhatiancura.</p>$h$ WHERE url='history-naming';

UPDATE public.pages SET title_en=$t$Geography & Location$t$,description_en=$d$Administrative identity, location, neighbouring areas, fields, and transport links of Dalimgari village.$d$,content_en=$h$<h2>Administrative Details</h2><ul><li><strong>Village:</strong> Dalimgari</li><li><strong>Mouza:</strong> Chhatiancura</li><li><strong>Post office:</strong> Kamdia</li><li><strong>Upazila and police station:</strong> Gobindaganj</li><li><strong>District:</strong> Gaibandha</li><li><strong>Division:</strong> Rangpur</li></ul>
<h2>Area and Environment</h2><p>According to information provided locally, the village covers approximately 1 square kilometre. It is reported that cultivated fields extend roughly half a kilometre to one kilometre around the village, beyond which other villages and markets are located.</p>
<h2>Neighbouring Areas</h2><ul><li><strong>East:</strong> Kamdia Bazar and Mohishmuri</li><li><strong>South:</strong> Terail</li><li><strong>West:</strong> Awlai Pakardaria</li><li><strong>North:</strong> Naoga Kathali and Bihigram</li><li><strong>Northeast corner:</strong> Chhatiancura</li></ul>
<h2>Transport Links</h2><p>There are four paved and unpaved roads leading into the village. A main road also runs beside the village, making it easier for residents to travel to Kamdia Bazar, other markets, and towns.</p>
<p><em>Area and distance measurements are approximate and have not been verified against maps or official records.</em></p>$h$ WHERE url='geography-location';

UPDATE public.pages SET title_en=$t$Agriculture & Economy$t$,description_en=$d$Agriculture-based livelihoods, major crops, and ways of earning a living in Dalimgari.$d$,content_en=$h$<h2>An Agriculture-Based Village</h2><p>Dalimgari is an agriculture-based village. According to locally supplied information, the livelihoods of most residents are directly or indirectly connected with crop cultivation.</p>
<h2>Main Crops</h2><h3>Rice</h3><p>Rice is the village's main crop and an important part of local agriculture.</p>
<h3>Potatoes</h3><p>Potatoes are identified as the village's second major crop after rice.</p>
<h3>Other Crops</h3><p>Small quantities of various fruits, vegetables, and other crops are also grown.</p>
<h2>Livelihoods and Income</h2><p>Alongside farming, residents also earn a living through business, salaried employment, and other occupations. The approximate occupational figures supplied locally are 50% farmers, 20% business owners and traders, 20% salaried employees, 5% other occupations, and 5% unemployed.</p>
<p><em>The basis and survey method for these occupational figures are not confirmed; they should be treated as approximate local information.</em></p>$h$ WHERE url='agriculture-economy';

-- Translate existing labels without deleting the original values.
UPDATE public.hero_items SET title_bn='ডালিমগাড়ীতে স্বাগতম' WHERE title_en='Welcome To Dalimgari';
UPDATE public.post SET title_bn='শীতকাল',caption_bn='শীতকাল' WHERE title_en='Winter';
UPDATE public.albums SET title_bn=CASE title_en WHEN 'Tribute' THEN 'শ্রদ্ধাঞ্জলি' WHEN 'Village' THEN 'গ্রাম' WHEN 'Nature' THEN 'প্রকৃতি ও দৃশ্যাবলি' ELSE title_bn END WHERE title_en IN ('Tribute','Village','Nature');
UPDATE public.widgets SET title_bn=CASE title_en WHEN 'Date & Time' THEN 'তারিখ ও সময়' WHEN 'Map' THEN 'মানচিত্র' ELSE title_bn END WHERE title_en IN ('Date & Time','Map');

NOTIFY pgrst, 'reload schema';
COMMIT;
